  const weapon=getItem(unit.equipment?.weapon),license=String(getAbility(unit.support)?.effect?.equipmentLicense || '').replace(/axes/,'axe').replace(/s$/,'');
  if(weapon && job.weaponTypes?.length && !job.weaponTypes.includes(weapon.subtype) && license!==weapon.subtype && job.id!=='onion') {
    campaign.inventory[weapon.id]=number(campaign.inventory[weapon.id])+1;delete unit.equipment.weapon;
  }
