  if (value && slot === 'secondaryJob' && !unlockedJobs(unit).includes(value)) return failure('This job is still locked.');
  if (value && slot !== 'secondaryJob' && (!unit.learned.includes(value) || getAbility(value)?.kind !== slot)) return failure('Learn a matching ability first.');
  unit[slot] = value || null;
