    const unlock = mission.unlock || {};
    const required = unlock.after || mission.requires || [];
    const after = Array.isArray(required) ? required : required ? [required] : [];
    if (after.some(id => !campaign.completed.includes(id))) return false;
    if ((unlock.all || []).some(id => !campaign.completed.includes(id))) return false;
    if (number(unlock.chapter,1) > campaign.chapter) return false;
