  if (active.remaining > 0) return failure(`The company returns in ${active.remaining} days.`);
  const baseReward=errand.reward || {gold:errand.gold,jp:errand.jp,items:errand.items};
  const multiplier=number(active.rewardMultiplier,1);
  const reward = {...baseReward,gold:Math.round(number(baseReward.gold,200)*multiplier),jp:Math.round(number(baseReward.jp,60)*multiplier),suitabilityBonus:multiplier-1};
  campaign.gold += number(reward.gold,200);
