    const oldLevel=roster.level;
    for(const field of ['level','exp','jp','jobExp','learned','equipment'])roster[field]=clone(participant[field]);
    for(const stat of ['bravery','attunement'])roster[stat]=clamp(number(roster[stat],65)+Math.trunc(number(participant.battleAttributes?.[stat])/4),0,100);
    roster.battles=number(roster.battles)+1;roster.kills=number(roster.kills)+number(participant.battleKills);
    if(victory){awardJP(roster,number(reward.jp,30));const gained=awardEXP(roster,60+clamp((number(state.mission.recommendedLevel,roster.level)-roster.level)*15,0,75));if(gained)levels.push({id:roster.id,name:roster.name,level:roster.level});}
