function hash(x,y,s=1){let v=Math.sin(x*127.1+y*311.7+s*73.17)*43758.5453;return v-Math.floor(v);}
function terrainColor(tile,p){if(/water|deep|shallow/.test(tile.terrain||''))return p.water;if(/road|stone|bridge|floor|cobble/.test(tile.terrain||''))return p.stone;return hash(tile.x,tile.y)>0.52?p.alt:p.top;}
