 setView({selected,highlights,targets,action,aoe,hover}={}){if(selected!==undefined)this.selected=selected;if(highlights!==undefined)this.highlights=highlights;if(targets!==undefined)this.targets=targets;if(action!==undefined)this.action=action;if(aoe!==undefined)this.aoe=aoe;if(hover!==undefined)this.hover=hover;}
